// FUNCTION: BFME2 0x001EEFD2 size=137 name=?setCursor@Mouse@@UAEXW4MouseCursor@1@@Z evidence=N:ledger tier=B hypothesis:Z
void Mouse::setCursor(MouseCursor cursor)
{
	if (m_currentCursor != cursor && m_cursorTextDisplayString && cursor >= 0 && (unsigned int)cursor < (unsigned int)NUM_MOUSE_CURSORS) {
		CursorInfo *info = &m_cursorInfo[cursor];
		if (!info->cursorText.isEmpty())
			setMouseText(TheGameText->fetch(info->cursorText.str(), 0), &info->cursorTextColor, &info->cursorTextDropColor);
		else
			setMouseText(UnicodeString(L""), 0, 0);
	}
}

