// FUNCTION: BFME2 0x001EF291 size=58 name=?getCursorIndex@Mouse@@QAEHABVAsciiString@@@Z evidence=N:ledger tier=B hypothesis:Z
int Mouse::getCursorIndex(const AsciiString &name)
{
	if (name.isEmpty())
		return -1;
	for (int i = 0; i < NUM_MOUSE_CURSORS; i++) {
		if (name.compareNoCase(s_mouseCursorNames[i]) == 0)
			return i;
	}
	return -1;
}

// FUNCTION: BFME2 0x001EF2CB size=125 name=?parseMouseCursorDefinition@INI@@SAXPAV1@@Z evidence=N:ledger tier=B hypothesis:Z

void INI::parseMouseCursorDefinition(INI *ini)
{
	AsciiString name;
	name.set(ini->getNextToken());
	if (TheMouse) {
		int index = TheMouse->getCursorIndex(name);
		if (index != Mouse::INVALID_MOUSE_CURSOR) {
			CursorInfo *cursorInfo = &TheMouse->m_cursorInfo[index];
			cursorInfo->cursorName = name;
			ini->initFromINI(cursorInfo, TheMouseCursorFieldParseTable);
		}
	}
}
